// .claude/settings.json
{
  "hooks": {
    "PostToolUse": [
      {
        "matcher": "Edit|Write",
        "hooks": [
          { "type": "command", "command": "npx prettier --write \"$CLAUDE_FILE_PATHS\" 2>/dev/null; npm run lint --silent || true" }
        ]
      }
    ],
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          { "type": "command", "command": "grep -Eq 'git add (\\.|-A|--all)' <<< \"$CLAUDE_TOOL_INPUT\" && { echo 'Blocked: stage individual files only'; exit 2; } || exit 0" }
        ]
      }
    ]
  }
}

